{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE rpsg_db.maplemonk.Dr_Level_Details AS WITH doctor_appointments AS ( SELECT d.DOCTORID AS doctor_id, d.\"Doctor Name\", a.ID AS appointment_id, a.DOCTORID AS appointment_doctor_id FROM RPSG_DB.MAPLEMONK.DRNAME_CONSULTATIONS d JOIN rpsg_db.maplemonk.pg_three60you_appointment a ON d.DOCTORID = a.DOCTORID ), invoicedatemetrics AS ( SELECT TRY_TO_DATE(FI.invoice_date) AS Invoice_Date, SUM(CASE WHEN FI.rr_flag IS NULL AND LOWER(FI.order_status) NOT IN (\'cancelled\') THEN IFNULL(FI.selling_price, 0) - IFNULL(FI.tax, 0) END) AS wo_rr_Realised_Revenue, SUM(IFNULL(CASE WHEN LOWER(FI.order_status) NOT IN (\'cancelled\') THEN IFNULL(FI.selling_price, 0) - IFNULL(FI.tax, 0) END, 0)) AS Realised_Revenue, DA.\"Doctor Name\" FROM RPSG_DB.MAPLEMONK.SALES_CONSOLIDATED_THREE60 FI LEFT JOIN doctor_appointments DA ON FI.appointment_id = DA.appointment_id WHERE NOT(LOWER(FI.order_status) IN (\'cancelled\')) AND FI.invoice_date != \'\' AND LOWER(FI.SHOP_NAME) = \'consultations\' GROUP BY TRY_TO_DATE(FI.invoice_date), DA.\"Doctor Name\" ORDER BY TRY_TO_DATE(FI.invoice_date) DESC ), returnsales AS ( SELECT return_date::DATE AS return_date, COUNT(DISTINCT CASE WHEN FI.rr_flag IS NULL THEN FI.reference_code END) AS wo_rr_return_orders_count, SUM(CASE WHEN FI.rr_flag IS NULL THEN IFNULL(total_return_amount_excl_tax, 0) END) AS wo_rr_TOTAL_RETURN_AMOUNT_EXCL_TAX, COUNT(DISTINCT FI.reference_code) AS return_orders_count, SUM(total_return_amount) AS TOTAL_RETURN_AMOUNT, SUM(total_return_amount_excl_tax) AS TOTAL_RETURN_AMOUNT_EXCL_TAX, SUM(total_returned_quantity) AS TOTAL_RETURNED_QUANTITY, DA.\"Doctor Name\" FROM RPSG_DB.MAPLEMONK.easyecom_returns_summary_three60 FI LEFT JOIN RPSG_DB.MAPLEMONK.SALES_CONSOLIDATED_THREE60 a ON FI.reference_code = a.ORDER_ID LEFT JOIN doctor_appointments DA ON a.appointment_id = DA.appointment_id WHERE LOWER(FI.SHOP_NAME) = \'consultations\' GROUP BY return_date, DA.\"Doctor Name\" ORDER BY return_date DESC ), orders AS ( SELECT FI.order_date::DATE AS Date, COUNT(DISTINCT FI.appointment_id) AS total_consultations, SUM(IFNULL(FI.selling_price, 0)) - SUM(IFNULL(FI.tax, 0)) AS Total_Sales_Ex_Tax, IFNULL(SUM(CASE WHEN FI.return_flag = 1 THEN FI.suborder_quantity END), 0) AS Return_Quantity, IFNULL(SUM(CASE WHEN FI.return_flag = 1 THEN IFNULL(FI.SELLING_PRICE, 0) END), 0) AS Return_Value, COUNT(DISTINCT CASE WHEN FI.return_flag = 1 THEN FI.order_id END) AS Return_Orders, COUNT(DISTINCT CASE WHEN LOWER(FI.final_status) IN (\'cancelled\') THEN FI.order_id END) AS Cancelled_Orders, COUNT(DISTINCT CASE WHEN LOWER(FI.order_status) NOT IN (\'cancelled\') AND FI.return_flag = 0 THEN FI.order_id END) AS Net_Orders, COUNT(DISTINCT CASE WHEN LOWER(FI.final_status) IN (\'delivered\') THEN FI.order_id END) AS Delivered_Orders, COUNT(DISTINCT CASE WHEN LOWER(FI.final_status) IN (\'returned\', \'rto\') THEN FI.order_id END) AS Returned_Orders, SUM(CASE WHEN LOWER(FI.final_status) IN (\'delivered\') THEN IFNULL(FI.SELLING_PRICE, 0) - IFNULL(FI.TAX, 0) END) AS Delivered_Revenue, SUM(CASE WHEN LOWER(FI.final_status) IN (\'returned\', \'rto\') THEN IFNULL(FI.SELLING_PRICE, 0) - IFNULL(FI.TAX, 0) END) AS Returned_Revenue, DA.\"Doctor Name\" FROM RPSG_DB.MAPLEMONK.SALES_CONSOLIDATED_THREE60 FI LEFT JOIN doctor_appointments DA ON FI.appointment_id = DA.appointment_id WHERE LOWER(FI.SHOP_NAME) = \'consultations\' GROUP BY FI.order_date::DATE, DA.\"Doctor Name\" ), consultations1 AS ( SELECT CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', start_timestamp::DATETIME)::DATE AS start_date, \'CONSULTATIONS\' AS c_marketplace, \'three60\' AS data_source, NULL AS c_channel, COUNT(DISTINCT CASE WHEN LOWER(status) = \'completed\' THEN id END) AS consultation_completed, COUNT(DISTINCT id) AS consultation_confirmed, \"Doctor Name\" FROM ( SELECT * FROM ( SELECT a.*, CASE WHEN LOWER(status) = \'completed\' THEN 1 ELSE 2 END AS df, RIGHT(REGEXP_REPLACE(c.phone, \'[^a-zA-Z0-9]+\'), 10) AS phone, ROW_NUMBER() OVER (PARTITION BY end_timestamp::DATE, phone ORDER BY df ASC) AS rw, d.\"Doctor Name\" FROM rpsg_db.maplemonk.pg_three60you_appointment a LEFT JOIN rpsg_db.maplemonk.pg_three60you_customer c ON LOWER(c.id) = LOWER(a.customer_id) LEFT JOIN rpsg_db.maplemonk.drname_consultations d ON a.DOCTORID = d.DOCTORID WHERE RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\'), 10) NOT IN ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\'), 10) FROM RPSG_DB.maplemonk.three60you_test_consultations ) ) WHERE rw = 1 ) WHERE start_date < CURRENT_DATE() GROUP BY 1, \"Doctor Name\" ORDER BY 1 DESC ), consultations AS ( SELECT COALESCE(start_date, start_date1) AS start_date, consultation_completed, consultation_confirmed, \'CONSULTATIONS\' AS c_marketplace, \'three60\' AS data_source, consultation_leads, COALESCE(a.\"Doctor Name\", b.\"Doctor Name\") AS \"Doctor Name\" FROM consultations1 a FULL OUTER JOIN ( SELECT CONVERT_TIMEZONE(\'UTC\',\'Asia/Kolkata\', created_at::DATETIME)::DATE AS start_date1, COUNT(DISTINCT id) AS consultation_leads, \"Doctor Name\" FROM ( SELECT * FROM ( SELECT a.*, CASE WHEN LOWER(a.status) = \'completed\' THEN 1 ELSE 2 END AS df, RIGHT(REGEXP_REPLACE(c.phone, \'[^a-zA-Z0-9]+\'), 10) AS phone, ROW_NUMBER() OVER (PARTITION BY a.end_timestamp::DATE, phone ORDER BY df ASC) AS rw, \"Doctor Name\" FROM rpsg_db.maplemonk.pg_three60you_appointment a LEFT JOIN rpsg_db.maplemonk.pg_three60you_customer c ON LOWER(c.id) = LOWER(a.customer_id) LEFT JOIN rpsg_db.maplemonk.drname_consultations d ON a.DOCTORID = d.DOCTORID WHERE RIGHT(REGEXP_REPLACE(c.phone, \'[^a-zA-Z0-9]+\'), 10) NOT IN ( SELECT DISTINCT RIGHT(REGEXP_REPLACE(phone, \'[^a-zA-Z0-9]+\'), 10) FROM RPSG_DB.maplemonk.three60you_test_consultations ) ) WHERE rw = 1 ) WHERE start_date1 < CURRENT_DATE() GROUP BY 1, \"Doctor Name\" ) b ON a.start_date = b.start_date1 AND LOWER(a.\"Doctor Name\") = LOWER(b.\"Doctor Name\") ) SELECT DISTINCT COALESCE(FI.Date, RS.return_date, IM.Invoice_Date, c.start_date) AS date, COALESCE(FI.\"Doctor Name\", RS.\"Doctor Name\", IM.\"Doctor Name\", c.\"Doctor Name\") AS \"Doctor Name\", consultation_completed, consultation_confirmed, consultation_leads, Return_Quantity, Return_Value, Total_Sales_Ex_Tax, wo_rr_TOTAL_RETURN_AMOUNT_EXCL_TAX, total_consultations, Net_Orders, Cancelled_Orders, Delivered_Orders, Delivered_Revenue, Realised_Revenue FROM orders FI FULL OUTER JOIN returnsales RS ON RS.return_date = FI.Date AND RS.\"Doctor Name\" = FI.\"Doctor Name\" FULL OUTER JOIN invoicedatemetrics IM ON IM.Invoice_Date = COALESCE(FI.Date, RS.return_date) AND IM.\"Doctor Name\" = COALESCE(FI.\"Doctor Name\", RS.\"Doctor Name\") FULL OUTER JOIN consultations c ON c.start_date = COALESCE(FI.Date, RS.return_date, IM.Invoice_Date) AND C.\"Doctor Name\" = COALESCE(FI.\"Doctor Name\", RS.\"Doctor Name\", IM.\"Doctor Name\") WHERE COALESCE(FI.\"Doctor Name\", RS.\"Doctor Name\", IM.\"Doctor Name\", c.\"Doctor Name\") IS NOT NULL;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from RPSG_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            